import { Meta, StoryObj } from "@storybook/react";
import ExpandContent, { ExpandContentWithoutState } from "./expand-content";
import { useState } from "react";

type StoryArgs = React.ComponentProps<typeof ExpandContent> & {
  isExpanded: boolean;
};

// Uses ExpandContentWithoutState in stories so that snapshots can be taken with exanded content and changes can be properly detected
const meta: Meta<StoryArgs> = {
  title: "Primitives/Expand Content",
  component: ExpandContent,
  render: function StoryComponent({ isExpanded, ...args }) {
    const [regularIsExpanded, setRegularIsExpanded] = useState(isExpanded);
    const [plainIsExpanded, setPlainIsExpanded] = useState(isExpanded);
    const [ghostIsExpanded, setGhostIsExpanded] = useState(isExpanded);

    return (
      <div style={{ padding: "1rem" }}>
        <h2>Regular</h2>
        <ExpandContentWithoutState
          buttonType="regular"
          {...args}
          isExpanded={regularIsExpanded}
          setIsExpanded={() => setRegularIsExpanded(!regularIsExpanded)}
        />

        <h2>Plain</h2>
        <ExpandContentWithoutState
          buttonType="plain"
          {...args}
          isExpanded={plainIsExpanded}
          setIsExpanded={() => setPlainIsExpanded(!plainIsExpanded)}
        />

        <h2>Ghost</h2>
        <ExpandContentWithoutState
          buttonType="ghost"
          {...args}
          isExpanded={ghostIsExpanded}
          setIsExpanded={() => setGhostIsExpanded(!ghostIsExpanded)}
        />
      </div>
    );
  },
};

export default meta;
type Story = StoryObj<StoryArgs>;

export const Default: Story = {
  args: {
    buttonPosition: "bottom",
    children: <div>This is the hidden content!</div>,
    isExpanded: false,
  },
};

export const Expanded: Story = {
  args: {
    ...Default.args,
    buttonPosition: "top",
    isExpanded: true,
  },
};

export const ButtonPositionTop: Story = {
  args: {
    ...Default.args,
    buttonPosition: "top",
  },
};

export const ButtonPositionTopExpanded: Story = {
  args: {
    ...Default.args,
    buttonPosition: "top",
    isExpanded: true,
  },
};

export const WithRightContent: Story = {
  args: {
    ...Default.args,
    rightContent: <div>Right content</div>,
  },
};

export const WithRightContentExpanded: Story = {
  args: {
    ...WithRightContent.args,
    rightContent: <div>Right content</div>,
    isExpanded: true,
  },
};
